// Captura o texto e a tag da entrada atual
const text = $json.output || "";
const subAgent = $json.sub_agent || "small_talk";

// Pega o id_bd correto direto do nó Filtra Dados
const idBd = $('Filtra Dados').first().json.id_bd; 

// Pega o número do WhatsApp diretamente do gatilho
const phoneNumber = $('WhatsApp Trigger').item.json.contacts[0].wa_id;

// Divide o texto onde houver duas ou mais quebras de linha seguidas
const paragraphs = text.split(/\n{2,}/);

// Transforma cada pedaço em um item individual contendo todas as colunas
return paragraphs
  .map(p => p.trim())
  .filter(p => p.length > 0)
  .map(p => ({ 
    json: { 
      output: p,                 // O texto fatiado da mensagem
      sub_agent: subAgent,       // O nome do sub-agente atual
      id_bd: idBd,               // O id_bd correto (1)
      phone_number: phoneNumber, // O número do WhatsApp do cliente
      message_id: null,          // Vazio/Nulo, pois mensagem de IA não possui wamid
      sender_type: "ai",         // Definido como 'ai'
      message_type: "text"       // Definido como 'text'
    } 
  }));

